/* Shared grubenv access for the Y4 slot machinery. See y4_grubenv.h. */
#define _GNU_SOURCE
#include "y4_grubenv.h"
#include <errno.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>

static const char signature[] =
    "# GRUB Environment Block\n"
    "# WARNING: Do not edit this file by tools other than grub-editenv!!!\n";

static const char *block_value(const unsigned char *block, const char *key) {
  size_t key_len = strlen(key);
  const unsigned char *p = block + strlen(signature);
  const unsigned char *end = block + Y4_GRUBENV_BYTES;
  while (p < end && *p && *p != '#') {
    const unsigned char *line_end = memchr(p, '\n', (size_t)(end - p));
    if (!line_end) break;
    if ((size_t)(line_end - p) > key_len &&
        !memcmp(p, key, key_len) && p[key_len] == '=') {
      size_t value_len = (size_t)(line_end - p) - key_len - 1;
      if (value_len >= 256) return NULL;
      static char value[256];
      memcpy(value, p + key_len + 1, value_len);
      value[value_len] = 0;
      return value;
    }
    p = line_end + 1;
  }
  return NULL;
}

int y4_grubenv_parse(const unsigned char *block, struct y4_slot_state *state) {
  if (!block || !state ||
      memcmp(block, signature, strlen(signature)) ||
      block[Y4_GRUBENV_BYTES - 1] != '#')
    return -EINVAL;
  memset(state, 0, sizeof *state);
  const char *value = block_value(block, "default");
  if (value) {
    char *endp; long parsed = strtol(value, &endp, 10);
    if (!*endp && (parsed == 0 || parsed == 1)) {
      state->have_default = 1; state->default_entry = (int)parsed;
    }
  }
  value = block_value(block, "slot");
  if (value && value[0] && !value[1] && (value[0] == 'A' || value[0] == 'B')) {
    state->have_slot = 1; state->slot[0] = value[0];
  }
  value = block_value(block, "boot_kernel");
  if (value && strlen(value) < sizeof state->boot_kernel) {
    state->have_boot_kernel = 1; strcpy(state->boot_kernel, value);
  }
  value = block_value(block, "boot_kernel_a");
  if (value && strlen(value) < sizeof state->boot_kernel_a) {
    state->have_boot_kernel_a = 1; strcpy(state->boot_kernel_a, value);
  }
  value = block_value(block, "boot_kernel_b");
  if (value && strlen(value) < sizeof state->boot_kernel_b) {
    state->have_boot_kernel_b = 1; strcpy(state->boot_kernel_b, value);
  }
  value = block_value(block, "boot_count");
  if (value) { char *endp; long parsed = strtol(value, &endp, 10);
    if (!*endp && parsed >= 0 && parsed < 1000000) state->boot_count = parsed; }
  value = block_value(block, "boot_ok");
  if (value) { char *endp; long parsed = strtol(value, &endp, 10);
    if (!*endp && parsed >= 0 && parsed <= 1) state->boot_ok = (int)parsed; }
  return 0;
}

int y4_grubenv_read(const char *path, struct y4_slot_state *state) {
  unsigned char block[Y4_GRUBENV_BYTES];
  int fd = open(path, O_RDONLY | O_CLOEXEC);
  if (fd < 0) return -errno;
  size_t got = 0;
  while (got < sizeof block) {
    ssize_t n = read(fd, block + got, sizeof block - got);
    if (n < 0) { int e = -errno; close(fd); return e; }
    if (!n) break;
    got += (size_t)n;
  }
  close(fd);
  if (got != sizeof block) return got ? -EINVAL : -ENOENT;
  return y4_grubenv_parse(block, state);
}

int y4_grubenv_render(const struct y4_slot_state *state, unsigned char *out) {
  if (!state || !out) return -EINVAL;
  /* The legacy boot_kernel key and the per-slot keys are each emitted only
   * when their have flag is set: an old grub.cfg keeps reading boot_kernel
   * on legacy boards, a new grub.cfg reads boot_kernel_a/b, and a writer
   * must never drop a key it does not understand. */
  char body[768];
  int n = snprintf(body, sizeof body,
                   "%s"
                   "default=%d\nslot=%s\n",
                   signature, state->default_entry,
                   state->slot[0] ? state->slot : "A");
  if (n < 0 || (size_t)n >= sizeof body) return -EOVERFLOW;
  if (state->have_boot_kernel) {
    int k = snprintf(body + n, sizeof body - (size_t)n, "boot_kernel=%s\n",
                     state->boot_kernel);
    if (k < 0 || (size_t)k >= sizeof body - (size_t)n) return -EOVERFLOW;
    n += k;
  }
  if (state->have_boot_kernel_a) {
    int k = snprintf(body + n, sizeof body - (size_t)n, "boot_kernel_a=%s\n",
                     state->boot_kernel_a);
    if (k < 0 || (size_t)k >= sizeof body - (size_t)n) return -EOVERFLOW;
    n += k;
  }
  if (state->have_boot_kernel_b) {
    int k = snprintf(body + n, sizeof body - (size_t)n, "boot_kernel_b=%s\n",
                     state->boot_kernel_b);
    if (k < 0 || (size_t)k >= sizeof body - (size_t)n) return -EOVERFLOW;
    n += k;
  }
  int k = snprintf(body + n, sizeof body - (size_t)n,
                   "boot_count=%ld\nboot_ok=%d\n", state->boot_count, state->boot_ok);
  if (k < 0 || (size_t)k >= sizeof body - (size_t)n) return -EOVERFLOW;
  n += k;
  if ((size_t)n > Y4_GRUBENV_BYTES) return -EOVERFLOW;
  memset(out, '#', Y4_GRUBENV_BYTES);
  memcpy(out, body, (size_t)n);
  return 0;
}

static int write_one(const char *path, const unsigned char *block) {
  char tmp[512];
  if ((size_t)snprintf(tmp, sizeof tmp, "%s.tmp-y4", path) >= sizeof tmp)
    return -ENAMETOOLONG;
  int fd = open(tmp, O_WRONLY | O_CREAT | O_TRUNC | O_CLOEXEC, 0600);
  if (fd < 0) return -errno;
  size_t at = 0;
  while (at < Y4_GRUBENV_BYTES) {
    ssize_t n = write(fd, block + at, Y4_GRUBENV_BYTES - at);
    if (n < 0) { int e = -errno; close(fd); unlink(tmp); return e; }
    at += (size_t)n;
  }
  if (fsync(fd)) { int e = -errno; close(fd); unlink(tmp); return e; }
  if (close(fd)) { unlink(tmp); return -errno; }
  if (rename(tmp, path)) { int e = -errno; unlink(tmp); return e; }
  /* Best effort: flush the directory entry so rename survives a reset. */
  int dir = open(path, O_RDONLY | O_DIRECTORY | O_CLOEXEC);
  if (dir >= 0) { (void)fsync(dir); close(dir); }
  return 0;
}

int y4_grubenv_write(const char *const *paths, const struct y4_slot_state *state) {
  unsigned char block[Y4_GRUBENV_BYTES];
  int e = y4_grubenv_render(state, block);
  if (e) return e;
  unsigned first = 1;
  const char *const *p = paths;
  for (; *p; p++, first = 0) {
    int w = write_one(*p, block);
    if (w) {
      /* All-or-nothing is not achievable across two filesystems without
       * journaling here; the /grub copy is the one grub reads, so report
       * its failure and keep the backup copy best-effort. */
      if (first) return w;
    }
  }
  return 0;
}
